CREATE COLUMN TABLE "TEST_AP"."SHR1" ("ShrId" INTEGER CS_INT NOT NULL , "RowId" INTEGER CS_INT NOT NULL , "CatId" SMALLINT CS_INT, "LineNum" NVARCHAR(6), "ItemName" NVARCHAR(254), "Level" SMALLINT CS_INT, "IndentChar" NVARCHAR(6), "Formula" NVARCHAR(1), "CurAmount" DECIMAL(21,6) CS_FIXED, "PreAmount" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("ShrId", "RowId")) UNLOAD PRIORITY 5  AUTO MERGE 